<template><PageShell title="Processo da Central de Guias"><div v-if="process" class="space-y-5"><section class="panel"><h2 class="section-title">Dados principais</h2><div class="grid gap-3 md:grid-cols-3"><p><b>Paciente</b><br>{{process.patient_name}}</p><p><b>Convênio</b><br>{{process.insurance_name}}</p><p><b>Fisioterapeuta</b><br>{{process.physiotherapist_name}}</p><p><b>Médico</b><br>{{process.doctor_name||'—'}}</p><p><b>Avaliação</b><br>{{date(process.assessment_date)}}</p><p><b>Início previsto</b><br>{{date(process.expected_start_date)}}</p></div></section><section class="panel"><h2 class="section-title">Documentação <span class="badge">{{process.document_status}}</span></h2><div class="grid gap-3 md:grid-cols-3"><article v-for="type in documentTypes" :key="type.key" class="rounded-xl border p-4"><b>{{type.label}}</b><div v-if="docs(type.key).length" class="mt-2"><div v-for="d in docs(type.key)" :key="d.id" class="text-sm"><p>{{d.original_name}}</p><p class="text-gray-500">{{date(d.created_at)}} · {{d.uploaded_by_name}}</p><button class="link" @click="download(d.id)">Visualizar</button></div></div><p v-else class="mt-2 text-sm text-orange-600">Pendente</p><label class="link mt-3 inline-block">{{docs(type.key).length&&type.key!=='OTHER'?'Substituir':'Enviar'}}<input class="hidden" type="file" accept=".pdf,.jpg,.jpeg,.png" @change="upload($event,type.key)"></label></article></div></section><section class="panel"><h2 class="section-title">Autorização</h2><div v-if="process.authorizations[0]" class="grid gap-3 md:grid-cols-3"><p>Status: {{process.authorizations[0].status}}</p><p>Número: {{process.authorizations[0].authorization_number||'—'}}</p><p>Validade: {{date(process.authorizations[0].expiration_date)}}</p><p>Solicitadas: {{process.authorizations[0].requested_sessions}}</p><p>Autorizadas: {{process.authorizations[0].authorized_sessions??'—'}}</p><p>{{process.authorizations[0].notes}}</p></div><p v-else class="text-gray-500">Nenhuma autorização registrada.</p><h3 class="mt-5 font-semibold">Pendências</h3><p v-for="item in process.pendingItems" :key="item.id" class="border-b py-2">{{item.description}} — {{item.status}}</p></section><section class="panel"><h2 class="section-title">Tratamento</h2><div class="grid grid-cols-2 gap-3 md:grid-cols-5"><p>Solicitadas<br><b>{{process.requested_sessions}}</b></p><p>Autorizadas<br><b>{{process.authorized_sessions??0}}</b></p><p>Realizadas<br><b>{{process.performed_sessions}}</b></p><p>Restantes<br><b>{{Math.max(0,(process.authorized_sessions||0)-process.performed_sessions)}}</b></p><p>Status<br><b>{{process.treatment_status}}</b></p></div></section><section class="panel"><h2 class="section-title">Histórico</h2><div v-for="h in process.history" :key="h.id" class="relative border-l-2 border-blue-200 py-2 pl-5"><b>{{labels[h.action]||h.action}}</b><p class="text-sm text-gray-500">{{h.user_name}} · {{new Date(h.created_at).toLocaleString('pt-BR')}}</p><p v-if="h.field" class="text-sm">{{h.field}}: {{h.old_value||'—'}} → {{h.new_value||'—'}}</p></div></section></div></PageShell></template>
<script setup lang="ts">/* eslint-disable @typescript-eslint/no-explicit-any */import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import api from '@/plugins/axios';import PageShell from '@/components/PageShell.vue';const route=useRoute(),process=ref<any>();const documentTypes=[['CONSULTATION_GUIDE','Guia de Consulta'],['PHYSIOTHERAPY_GUIDE','Guia de Fisioterapia'],['PHYSIO_ASSESSMENT','Avaliação'],['ELECTROSTIMULATION','Eletroestimulação'],['INSURANCE_CARD','Carteirinha'],['OTHER','Outros']].map(([key,label])=>({key,label}));const labels:Record<string,string>={PROCESS_CREATED:'Processo criado',DOCUMENT_UPLOADED:'Documento enviado',DOCUMENT_REPLACED:'Documento substituído',DOCUMENT_REMOVED:'Documento removido',STATUS_CHANGED:'Status alterado',AUTHORIZATION_CREATED:'Autorização incluída',AUTHORIZATION_UPDATED:'Autorização alterada',PENDING_ITEM_CREATED:'Pendência criada',PENDING_ITEM_RESOLVED:'Pendência resolvida'};const date=(v:string)=>v?new Date(v).toLocaleDateString('pt-BR'):'—';const docs=(type:string)=>process.value.documents.filter((d:any)=>d.document_type===type);async function download(id:number){const response=await api.get(`/documents/${id}/download`,{responseType:'blob'});window.open(URL.createObjectURL(response.data),'_blank')}async function load(){process.value=(await api.get(`/guide-processes/${route.params.id}`)).data}async function upload(event:Event,type:string){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await api.post(`/guide-processes/${route.params.id}/documents`,file,{params:{documentType:type},headers:{'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name)}});await load()}onMounted(load);</script>
